{
  "name": "genesis-charter-lab",
  "version": "1.0.0",
  "description": "Evaluate public role instructions before promotion.",
  "main": "index.cjs",
  "type": "commonjs",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test",
    "demo": "node examples/demo.cjs"
  },
  "license": "MIT",
  "author": "Genesis Contributors",
  "repository": {
    "type": "git",
    "url": "https://github.com/Wassimyounes01/genesis-charter-lab.git"
  },
  "homepage": "https://github.com/Wassimyounes01/genesis-charter-lab#readme",
  "bugs": {
    "url": "https://github.com/Wassimyounes01/genesis-charter-lab/issues"
  }
}

'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createCharterLab, evidenceDigest } = require('../index.cjs');
function verifier(evidence) { return { ok: true, proofDigest: evidence.proofDigest, artifactId: evidence.artifactId, currentHash: evidence.currentHash, independentReview: true }; }
function setup() { const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'genesis-charter-')); return { dir, lab: createCharterLab({ stateDir: dir, verifyEvidence: verifier }) }; }
function receipt(lab, hash, taskId, split, score = 11) { lab.preregister({ candidateHash: hash, metric: 'quality', minimumRelativeGain: 0.05, taskId, split }); const input = { candidateHash: hash, baselineHash: lab.snapshot().candidates[hash].baselineHash, taskId, split, metric: 'quality', minimumRelativeGain: 0.05, artifactId: `artifact-${taskId}`, currentHash: hash, measuredAt: new Date().toISOString(), baselineScore: 10, candidateScore: score, regressions: 0 }; lab.recordEvidence({ ...input, proofDigest: evidenceDigest(input) }); }
function fill(lab, hash, suffix = '') {
  for (let i = 0; i < 3; i++) receipt(lab, hash, `train-${i}${suffix}`, 'train');
  receipt(lab, hash, `holdout${suffix}`, 'holdout');
}
test('stages a hashed candidate and requires preregistration after staging', () => { const { lab } = setup(); const candidate = lab.stage({ role: 'planner', text: 'Plan with explicit evidence.', rationale: 'Test bounded planning.' }); assert.equal(candidate.hash.length, 64); assert.throws(() => lab.recordEvidence({ candidateHash: candidate.hash, baselineHash: candidate.baselineHash, taskId: 'x', split: 'train', artifactId: 'a', currentHash: candidate.hash, measuredAt: new Date().toISOString(), proofDigest: 'a'.repeat(64), baselineScore: 1, candidateScore: 2, regressions: 0 }), /preregistered/); });
test('promotion requires three training and a separate holdout benefit', () => { const { lab } = setup(); const c = lab.stage({ role: 'worker', text: 'Execute bounded work and return evidence.', rationale: 'Improve handoffs.' }); assert.throws(() => lab.promote({ candidateHash: c.hash }), /three training/); fill(lab, c.hash); const promoted = lab.promote({ candidateHash: c.hash }); assert.equal(promoted.status, 'promoted'); assert.equal(lab.get('worker').version, c.hash); });
test('regression or missing measured benefit blocks promotion', () => { const { lab } = setup(); const c = lab.stage({ role: 'worker', text: 'Candidate with no benefit.', rationale: 'Negative fixture.' }); for (let i = 0; i < 3; i++) receipt(lab, c.hash, `t-${i}`, 'train', 10); receipt(lab, c.hash, 'h', 'holdout'); assert.throws(() => lab.promote({ candidateHash: c.hash }), /benefit/); });
test('rollback retains history and returns to baseline', () => { const { lab } = setup(); const c = lab.stage({ role: 'planner', text: 'A promoted planner.', rationale: 'Rollback fixture.' }); fill(lab, c.hash, '-p'); lab.promote({ candidateHash: c.hash }); const result = lab.rollback({ role: 'planner', reason: 'Held-out regression found later.' }); assert.equal(result.status, 'rolled-back'); assert.equal(lab.get('planner').source, 'baseline'); assert.equal(lab.snapshot().history.at(-1).action, 'rollback'); });
test('token evidence requires measured positive counts', () => { const { lab } = setup(); const c = lab.stage({ role: 'worker', text: 'Token measured candidate.', rationale: 'Cost check.' }); lab.preregister({ candidateHash: c.hash, metric: 'tokens', minimumRelativeGain: 0.1, taskId: 't', split: 'train' }); assert.throws(() => lab.recordEvidence({ candidateHash: c.hash, taskId: 't', split: 'train', artifactId: 'a', currentHash: c.hash, measuredAt: new Date().toISOString(), proofDigest: 'a'.repeat(64), baselineScore: 1, candidateScore: 1, regressions: 0 }), /token counts/); });
test('verification is required and must match the exact proof binding', () => { const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'genesis-charter-no-proof-')); const lab = createCharterLab({ stateDir: dir }); const c = lab.stage({ role: 'worker', text: 'No unverified evidence.', rationale: 'Safety fixture.' }); lab.preregister({ candidateHash: c.hash, metric: 'quality', minimumRelativeGain: 0.05, taskId: 't', split: 'train' }); const fields = { candidateHash: c.hash, baselineHash: c.baselineHash, taskId: 't', split: 'train', metric: 'quality', minimumRelativeGain: 0.05, artifactId: 'a', currentHash: c.hash, measuredAt: new Date().toISOString(), baselineScore: 1, candidateScore: 2, regressions: 0 }; assert.throws(() => lab.recordEvidence({ ...fields, proofDigest: evidenceDigest(fields) }), /verifier/); const bad = createCharterLab({ stateDir: fs.mkdtempSync(path.join(os.tmpdir(), 'genesis-charter-bad-proof-')), verifyEvidence: () => ({ ok: true, proofDigest: 'a'.repeat(64), artifactId: 'a', currentHash: c.hash, independentReview: true }) }); const c2 = bad.stage({ role: 'worker', text: 'Bad proof.', rationale: 'Safety fixture.' }); bad.preregister({ candidateHash: c2.hash, metric: 'quality', minimumRelativeGain: 0.05, taskId: 't', split: 'train' }); const badFields = { candidateHash: c2.hash, baselineHash: c2.baselineHash, taskId: 't', split: 'train', metric: 'quality', minimumRelativeGain: 0.05, artifactId: 'a', currentHash: c2.hash, measuredAt: new Date().toISOString(), baselineScore: 1, candidateScore: 2, regressions: 0 }; assert.throws(() => bad.recordEvidence({ ...badFields, proofDigest: evidenceDigest(badFields) }), /proof/); });
test('rollback cannot target a promoted candidate from another role', () => { const { lab } = setup(); const planner = lab.stage({ role: 'planner', text: 'Planner candidate.', rationale: 'Role binding.' }); fill(lab, planner.hash, '-planner'); lab.promote({ candidateHash: planner.hash }); const worker = lab.stage({ role: 'worker', text: 'Worker candidate.', rationale: 'Role binding.' }); fill(lab, worker.hash, '-worker'); lab.promote({ candidateHash: worker.hash }); assert.throws(() => lab.rollback({ role: 'planner', version: worker.hash, reason: 'wrong role fixture' }), /prior promoted version or baseline/); });
test('proof digest binds regressions and measured freshness', () => { const { lab } = setup(); const c = lab.stage({ role: 'worker', text: 'Digest binding candidate.', rationale: 'Regression fixture.' }); lab.preregister({ candidateHash: c.hash, metric: 'quality', minimumRelativeGain: 0.05, taskId: 'digest-task', split: 'train' }); const fields = { candidateHash: c.hash, baselineHash: c.baselineHash, taskId: 'digest-task', split: 'train', metric: 'quality', minimumRelativeGain: 0.05, artifactId: 'artifact-digest', currentHash: c.hash, measuredAt: new Date().toISOString(), baselineScore: 10, candidateScore: 11, regressions: 1 }; const clean = { ...fields, regressions: 0 }; assert.notEqual(evidenceDigest(fields), evidenceDigest(clean)); assert.throws(() => lab.recordEvidence({ ...fields, proofDigest: evidenceDigest(clean) }), /proofDigest/); const oldAt = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(); const old = { ...clean, measuredAt: oldAt, proofDigest: evidenceDigest({ ...clean, measuredAt: oldAt }) }; assert.throws(() => lab.recordEvidence(old), /preregistration|freshness/); });
